/* ===== ARCHITECT WAY — meta + Atos I–III ===== */
SYS.lib({
  fosa:{t:'Fundamentals of Software Architecture — A Modern Engineering Approach',a:'Mark Richards & Neal Ford',y:'2ª ed. · 2025',w:'architect',note:'Características arquiteturais, trade-offs, modularidade, estilos e pensamento de decisão. Faça 1 página por capítulo: problema / decisão / anti-padrão.'},
  hardparts:{t:'Software Architecture: The Hard Parts',a:'Ford, Richards, Sadalage & Dehghani',y:'2021',w:'architect',note:'Leia por problema, não de capa a capa: decomposição, posse de dados, acoplamento distribuído. Pelo menos 2 ADRs devem citar trade-offs daqui.'},
  sap:{t:'Software Architecture in Practice',a:'Bass, Clements & Kazman',y:'4ª ed. · 2021',w:'architect',note:'Cenários de atributos de qualidade e táticas arquiteturais. Referência, não leitura corrida.'},
  sa4dev:{t:'Software Architecture for Developers',a:'Simon Brown',y:'Leanpub (atualizado)',w:'architect',note:'Do criador do C4: como desenhar e comunicar arquitetura sem virar “arquiteto de PowerPoint”.'},
  elevator:{t:'The Software Architect Elevator',a:'Gregor Hohpe',y:'2020',w:'architect',note:'Como transitar entre a diretoria e a sala de máquinas. Essencial para CTO fracionado.'},
  momtest:{t:'The Mom Test',a:'Rob Fitzpatrick',y:'2013',w:'founder',note:'Como fazer entrevistas com clientes sem ouvir mentiras educadas.'},
  umlDistilled:{t:'UML Distilled',a:'Martin Fowler',y:'3ª ed. · 2003',pt:'UML Essencial (Bookman)',w:'architect',note:'Só o UML que importa: sequência, estados, atividade.'},
  coupling:{t:'Balancing Coupling in Software Design',a:'Vlad Khononov',y:'2024',w:'architect',note:'Modelo força × distância × volatilidade para decidir onde acoplamento é aceitável.'},
  refactoring:{t:'Refactoring',a:'Martin Fowler',y:'2ª ed. · 2018',pt:'Refatoração (Novatec)',w:'architect',note:'Catálogo de refatorações seguras; como pagar dívida técnica sem quebrar tudo.'},
  cleanArch:{t:'Clean Architecture',a:'Robert C. Martin',y:'2017',pt:'Arquitetura Limpa (Alta Books)',w:'architect',note:'Regra de dependência e princípios de componentes. Leia com senso crítico: evite cerimônia.'},
  mono2micro:{t:'Monolith to Microservices',a:'Sam Newman',y:'2019',w:'architect',note:'Quando (e se) dividir um monólito; padrões de migração incremental.'},
  buildingms:{t:'Building Microservices',a:'Sam Newman',y:'2ª ed. · 2021',w:'architect',note:'Modelagem de serviços, comunicação, deploy e — principalmente — quando não usar microserviços.'},
  aspnetInAction:{t:'ASP.NET Core in Action',a:'Andrew Lock',y:'3ª ed. · 2023',w:'architect',note:'Pipeline, roteamento, DI, configuração e segurança no ASP.NET Core.'},
  hpbn:{t:'High Performance Browser Networking',a:'Ilya Grigorik',y:'grátis online',u:'https://hpbn.co/',w:'architect',note:'TCP, TLS, HTTP/1-2-3 e latência explicados para quem constrói sistemas.'},
  diBook:{t:'Dependency Injection Principles, Practices, and Patterns',a:'Steven van Deursen & Mark Seemann',y:'2019',w:'architect',note:'Lifetimes, composition root e anti-padrões (service locator, captive dependency).'},
  csharp14:{t:'C# 14 and .NET 10 – Modern Cross-Platform Development Fundamentals',a:'Mark J. Price',y:'10ª ed. · 2025',w:'architect',note:'Base atualizada de C#/.NET 10, ASP.NET Core, EF Core e Blazor.'},
  bea:{t:'Building Evolutionary Architectures',a:'Ford, Parsons, Kua & Sadalage',y:'2ª ed. · 2022',w:'architect',note:'Fitness functions e evolução governada. Defina 3 checagens de arquitetura que rodam periodicamente.'},
  lddd:{t:'Learning Domain-Driven Design',a:'Vlad Khononov',y:'2021',w:'architect',note:'A introdução mais prática a DDD estratégico + tático. Aplique cada conceito a um negócio real.'},
  dddd:{t:'Domain-Driven Design Distilled',a:'Vaughn Vernon',y:'2016',w:'architect',note:'Versão curta de DDD: bounded contexts, linguagem ubíqua, agregados. Nenhum termo pode ficar abstrato.'},
  ddd:{t:'Domain-Driven Design',a:'Eric Evans',y:'2003',pt:'Domain-Driven Design: Atacando as Complexidades no Coração do Software (Alta Books)',w:'architect',note:'O livro azul original. Leia depois do Khononov/Vernon, focando nas partes estratégicas.'},
  unitTesting:{t:'Unit Testing: Principles, Practices, and Patterns',a:'Vladimir Khorikov',y:'2020',w:'architect',note:'O que testar, o que não mockar e como testes protegem refatoração.'},
  promptEngLLM:{t:'Prompt Engineering for LLMs',a:'John Berryman & Albert Ziegler',y:'2024',w:'architect',note:'Como montar contexto, estruturar pedidos e avaliar respostas de LLMs.'},
  ddia:{t:'Designing Data-Intensive Applications',a:'Martin Kleppmann & Chris Riccomini',y:'2ª ed. · 2026',w:'architect',note:'Modelos de dados, armazenamento, replicação, particionamento, transações e streams. Explique cada capítulo usando o cenário filial/matriz.'},
  sqlAntipatterns:{t:'SQL Antipatterns, Volume 1',a:'Bill Karwin',y:'2ª ed. · 2022',w:'architect',note:'Os erros clássicos de modelagem e consulta — e como sair deles.'},
  refactoringDatabases:{t:'Refactoring Databases',a:'Scott Ambler & Pramod Sadalage',y:'2006',w:'architect',note:'Mudança evolutiva de schema: expand/contract, períodos de transição.'},
  sqlPerf:{t:'SQL Performance Explained',a:'Markus Winand',y:'2012',u:'https://use-the-index-luke.com/',w:'architect',note:'Índices e planos de execução de verdade (versão web grátis: Use The Index, Luke).'},
  dbInternals:{t:'Database Internals',a:'Alex Petrov',y:'2019',w:'architect',note:'B-trees, LSM, replicação e consenso por dentro. Aprofundamento opcional.'},
  apiPatterns:{t:'API Design Patterns',a:'JJ Geewax',y:'2021',w:'architect',note:'Paginação, filtros, operações longas, versionamento — padrões com trade-offs.'},
  webApiDesign:{t:'The Design of Web APIs',a:'Arnaud Lauret',y:'Manning',w:'architect',note:'Design de API centrado no consumidor e contratos OpenAPI.'}
});

